<?php
require_once __DIR__ . '/includes/db_connection.php'; require_once __DIR__ . '/includes/functions.php'; require_once __DIR__ . '/includes/master_data.php';
startSecureSession(); requireLogin(); $conn=getDBConnection(); ensurePODSchema($conn); $id=(int)($_GET['id']??0);
$stmt=$conn->prepare('SELECT c.consignment_note,p.id,p.original_name,p.mime_type,p.file_size,p.uploaded_at FROM consignments c JOIN pod_files p ON p.consignment_id=c.id WHERE c.id=? ORDER BY p.uploaded_at DESC');$stmt->bind_param('i',$id);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();
?><!doctype html><html><head><meta charset="utf-8"><title>POD Files</title><link rel="stylesheet" href="css/style.css"><style>body{overflow:auto;background:#edf3f8}.pod-gallery{max-width:1100px;margin:26px auto;background:#fff;padding:22px;border-radius:12px;box-shadow:0 8px 24px #1a527622}.pod-gallery h2{color:#0f4c5c}.pod-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:14px}.pod-file-card{border:1px solid #d6e2e8;border-radius:10px;padding:9px;background:#fafdff}.pod-thumb{width:100%;height:130px;object-fit:cover;border-radius:7px;cursor:zoom-in;transition:transform .2s,box-shadow .2s}.pod-thumb:hover{transform:scale(1.7);position:relative;z-index:3;box-shadow:0 8px 20px #0005}.pod-pdf{height:130px;display:flex;align-items:center;justify-content:center;background:#fff1f1;color:#c0392b;border-radius:7px;font-size:2.4rem}.pod-name{font-size:.7rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:7px 0}.pod-download{font-size:.7rem;color:#0f766e;font-weight:700;text-decoration:none}</style></head><body><main class="pod-gallery"><a href="pod_upload.php?view=uploaded">← POD Uploaded List</a><h2>Uploaded PODs <?= $rows ? '— '.htmlspecialchars($rows[0]['consignment_note']) : '' ?></h2><div class="pod-grid"><?php foreach($rows as $row):$url='api/download_pod.php?id='.$row['id'];$image=strpos($row['mime_type'],'image/')===0;?><article class="pod-file-card"><?php if($image):?><a href="<?=$url?>" target="_blank"><img class="pod-thumb" src="<?=$url?>" alt="<?=htmlspecialchars($row['original_name'])?>"></a><?php else:?><div class="pod-pdf">PDF</div><?php endif;?><div class="pod-name" title="<?=htmlspecialchars($row['original_name'])?>"><?=htmlspecialchars($row['original_name'])?></div><small><?=number_format($row['file_size']/1024,1)?> KB · <?=htmlspecialchars($row['uploaded_at'])?></small><br><a class="pod-download" href="<?=$url?>&download=1">⇩ Download</a></article><?php endforeach;?></div><?php if(!$rows):?><p>No POD files found.</p><?php endif;?></main></body></html>
